      block data mollnix                                                        !/*mo          1*/
#ifdef CEM                                                                      /*!mo          2*/
! ======================================================================        !/*mo          3*/
!                                                                               !/*mo          4*/
!   This block data routine enters the microscopic correction to the            !/*mo          5*/
!   macroscopic mass of the spherical macroscopic ground state and the          !/*mo          6*/
!   experimental mass excess, (or the calculated one for nuclei without         !/*mo          7*/
!   a measured mass excess) according to the Finite-Range Liquid Drop           !/*mo          8*/
!   Model of nuclear masses. [P. Moller, J. R. Nix, W. D. Myers, and            !/*mo          9*/
!   W. J. Swiatecki, Atomic Data Nucl. Data Tables, 59, 185 (1995)]             !/*mo         10*/
!   The less accurate FRLDM is used (instead of the FRDM), because that         !/*mo         11*/
!   is the model used to calculate fission barrier heights in the Sierk         !/*mo         12*/
!   BARFIT routine which is used in CEM97a.                                     !/*mo         13*/
!                                                                               !/*mo         14*/
!   The routine also enters the pairing gap (energy shift) to be used           !/*mo         15*/
!   in nuclear level density formulas, derived from                             !/*mo         16*/
!   the tables of Moller, Nix, & Kratz (1996). For odd-Z, even-N nuclei,        !/*mo         17*/
!   the energy shift is delta-n from the M, N, & K table;                       !/*mo         18*/
!   for odd-N, even-Z, delta-p; and for even-even nuclei, the correction        !/*mo         19*/
!   is delta-p + delta-n.                                                       !/*mo         20*/
!                                                                               !/*mo         21*/
!   For each value of Z, the values of N from Nmin(Z) to Nmax(Z)                !/*mo         22*/
!   are included in the table.                                                  !/*mo         23*/
!   The Z index of the arrays nmin, nmax, emic1, epair1, and emx1               !/*mo         24*/
!   is equal to Z - 7, since the tables only contain entries for                !/*mo         25*/
!   Z,N > 7. For emic2, emx2, & epair2, the index is Z - 34;                    !/*mo         26*/
!   For emic3, emx3, & epair3, the index is Z - 47; and                         !/*mo         27*/
!   for emicr, emxr, & epair4, the index is Z - 70.                             !/*mo         28*/
!   The N index corresponds to N - Nmin(Z) + 1.                                 !/*mo         29*/
!   The table contains Z values from 8 to 100, and N values from the            !/*mo         30*/
!   most neutron-deficient isotope in the original table to                     !/*mo         31*/
!   approximately 5-10  neutrons above the most neutron rich isotope            !/*mo         32*/
!   which exists in nature (or has a long half life, for elements with          !/*mo         33*/
!   no stable isotopes).  This asymmetry acknowledges the fact that the         !/*mo         34*/
!   isotopes encountered in the decay of nuclei will start near the             !/*mo         35*/
!   line of beta stability, and move to the neutron deficient region,           !/*mo         36*/
!   as evaporation and pre-equilbrium decay proceed.                            !/*mo         37*/
!   Tables added for 1 <= Z <= 7, 11/97                                         !/*mo         38*/
!                                                                               !/*mo         39*/
!   Written by A. J. Sierk,  LANL  T-2,  April-May, 1996.                       !/*mo         40*/
!   Modified by AJS, November, 1997.                                            !/*mo         41*/
!   Changed to double by F. Gallmeier, ORNL CPED, October 1998.                 !/*mo         42*/
!                                                                               !/*mo         43*/
! ======================================================================        !/*mo         44*/
#include <cem/cdouble.h>                                                        /*!mo         45*/
      common /nsmnix/ nmin(93), nmax(93)                                        !/*mo         46*/
      common /emcnix/ emic1(30,27), emic2(35,13), emic3(40,17),                 !/*mo         47*/
     &                emic4(45,36)                                              !/*mo         48*/
      common /emxnix/ emx1(30,27), emx2(35,13), emx3(40,17), emx4(45,36)        !/*mo         49*/
      common /eprnix/ epair1(30,27), epair2(35,13), epair3(40,17),              !/*mo         50*/
     &                epair4(45,36)                                             !/*mo         51*/
      common /mxnix2/ emxa(15,7), nmina(7), nmaxa(7)                            !/*mo         52*/
      common /mcnix2/ emica(15,7), epaira(15,7)                                 !/*mo         53*/
      data nmina /0,  1,  1,  2,  2,  2,  4/                                    !/*mo         54*/
      data nmaxa /5,  8,  8, 10, 12, 14, 15/                                    !/*mo         55*/
      data nmin /                             4,  6,  6,                        !/*mo         56*/
     &            8,  8,  8,  8,  8,  8,  8,  9, 10, 10,                        !/*mo         57*/
     &           11, 12, 13, 14, 15, 16, 17, 18, 19, 21,                        !/*mo         58*/
     &           22, 23, 24, 25, 26, 27, 29, 30, 31, 32,                        !/*mo         59*/
     &           33, 35, 36, 37, 38, 40, 41, 42, 43, 44,                        !/*mo         60*/
     &           46, 47, 48, 49, 51, 52, 53, 55, 56, 58,                        !/*mo         61*/
     &           59, 61, 62, 64, 65, 67, 69, 70, 72, 73,                        !/*mo         62*/
     &           75, 77, 78, 80, 81, 83, 85, 87, 88, 90,                        !/*mo         63*/
     &           92, 93, 95, 97, 99,100,102,104,106,108,                        !/*mo         64*/
     &          109,111,113,115,117,119,121,123,125,126/                        !/*mo         65*/
      data nmax /                            16, 18, 20,                        !/*mo         66*/
     &           22, 22, 24, 24, 26, 27, 28, 29, 31, 32,                        !/*mo         67*/
     &           33, 34, 38, 39, 40, 41, 42, 44, 44, 50,                        !/*mo         68*/
     &           51, 52, 53, 54, 58, 59, 62, 62, 63, 64,                        !/*mo         69*/
     &           66, 68, 69, 70, 72, 74, 75, 81, 82, 83,                        !/*mo         70*/
     &           85, 86, 87, 88, 90, 91, 92, 94, 95, 97,                        !/*mo         71*/
     &           98,100,101,103,109,111,113,114,116,117,                        !/*mo         72*/
     &          119,121,122,124,125,127,129,131,132,134,                        !/*mo         73*/
     &          136,137,139,141,143,144,146,148,150,152,                        !/*mo         74*/
     &          153,155,157,159,159,160,160,162,164,165/                        !/*mo         75*/
!   Microscopic corrections to the ground state mass; Consists of               !/*mo         76*/
!   shell, pairing, and macroscopic deformation energy. (The deformation        !/*mo         77*/
!   of the ground state shape is due to microscopic corrections to the          !/*mo         78*/
!   macroscopic potential energy surface.)                                      !/*mo         79*/
!   Non-zero values only for N >= Nmin(Z) and N <= Nmax(Z).                     !/*mo         80*/
!                                                                               !/*mo         81*/
! Z = 1 to 7   Difference between measured mass excess and calculated           !/*mo         82*/
!              spherical macroscopic values.                                    !/*mo         83*/
      data emica /                                                              !/*mo         84*/
     & -40.60d0,-10.69d0, -7.41d0, -9.42d0, -8.11d0,-17.42d0, 9*0.0d0,          !/*mo         85*/
     &  -7.08d0, -1.73d0, -4.16d0, -3.45d0, -7.22d0, -9.00d0,-12.89d0,          !/*mo         86*/
