     &   1.85d0,  1.44d0, 4*0.0d0,                                              !/*mo         95*/
     &  -9.16d0, -0.71d0,  2.23d0,  3.28d0,  1.27d0,  0.64d0,  0.40d0,          !/*mo         96*/
     &   1.12d0,  2.41d0,                                                       !/*mo         97*/
     &   1.86d0,  1.37d0, -0.03d0, -1.07d0, 2*0.0d0,                            !/*mo         98*/
